package demo;

public class largest3number {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=10;
		int b=20;
		int c=5;
	if(a>b && a>c) {
		System.out.println("A is largest"+a);
	
	}
	
	 if(b>a && b>c) {
		System.out.println("B is largest"+b);
	 }
	 
	 else {
		 System.out.println("C is largest"+c);
	 }


}
}
	 
